import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int x = scanner.nextInt();
        int y = scanner.nextInt();

        if (x == y) {
            System.out.println("No");
            return;
        } else if (x < y) {
            if (y - x == 1) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        } else {
            if (y == 0 || y == 1) {
                System.out.println("No");
                return;
            }
            y = y - 1;
            x = x - y;
            if ((x & 1) != 0) {
                System.out.println("No");
            } else {
                System.out.println("Yes");
            }
        }
    }
}

